SELECT result.id_user AS user_id,result.id_record AS record_id,"user".steam_id, "user".steam_name,result.time,result.rank,result.points FROM public.track_tournament_result result JOIN public."user" ON "user".id=result.id_user WHERE result.id_tournament=$1 AND "user".steam_id=ANY($2) ORDER BY result.rank,result.time,result.id_record LIMIT 64
